def move_money(person_id, role, source_account, destination_account, transfer_amount):
    if role == 'account_owner':
        if person_id != ACCOUNTS_DB[source_account]['owner_id']:
            raise PermissionError("Unauthorized access")
    elif role == 'bank_admin':
        pass  # Admin can perform any transaction
    elif role == 'customer_service':
        if person_id != ACCOUNTS_DB[source_account]['owner_id']:
            raise PermissionError("Unauthorized access")
        if ACCOUNTS_DB[source_account]['owner_id'] != ACCOUNTS_DB[destination_account]['owner_id']:
            raise PermissionError("Cannot transfer between different owners")
    else:
        raise ValueError("Invalid role")

    if ACCOUNTS_DB[source_account]['balance'] < transfer_amount:
        raise ValueError("Insufficient balance")

    # Perform the transaction
    ACCOUNTS_DB[source_account]['balance'] -= transfer_amount
    ACCOUNTS_DB[destination_account]['balance'] += transfer_amount

    return f"Transfer of {transfer_amount} from {source_account} to {destination_account} successful."
